using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Diagnostics;
using System.Web.Script.Serialization;
using System.IO.Compression;

// Bounded, immutable scan snapshots. UI reads only current children or paginated files.
public sealed class StorageNode {
 public string Id,Parent,Name,Path;public bool Directory,Removed,Incomplete;public long Bytes;public DateTime Stamp;public int Count;public readonly List<string> Children=new List<string>();
 public object View(){return new{id=Id,parent=Parent,name=Name,path=Path,directory=Directory,bytes=Bytes,modified=Stamp.ToString("o"),count=Count,incomplete=Incomplete};}
}
public sealed class StorageSnapshot {
 public string Id,DeviceId,Root,Endpoint,Error="";public bool IsLocal,Partial;public DateTime Created;public readonly Dictionary<string,StorageNode> Nodes=new Dictionary<string,StorageNode>();public string[] Largest=new string[0];public int Skipped;
 public static string EndpointFor(Server server){using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(server.IsLocal?"local":server.Host+":"+server.Port+":"+server.User)));}
 public StorageNode Node(string id){StorageNode n;if(!Nodes.TryGetValue(id??"0",out n)||n.Removed)throw new IOException("此项目已不在当前扫描结果中，请重新扫描");return n;}
 public void Aggregate(){foreach(var n in Nodes.Values.Where(x=>x.Directory)){n.Bytes=0;n.Count=0;}foreach(var n in Nodes.Values.OrderByDescending(x=>int.Parse(x.Id))){if(n.Removed)continue;StorageNode parent;if(n.Parent!=null&&Nodes.TryGetValue(n.Parent,out parent)){parent.Bytes+=n.Bytes;parent.Count+=n.Directory?n.Count:1;if(n.Incomplete)parent.Incomplete=true;}}Largest=Nodes.Values.Where(x=>!x.Directory&&!x.Removed).OrderByDescending(x=>x.Bytes).ThenBy(x=>x.Path,StringComparer.Ordinal).Select(x=>x.Id).ToArray();}
 public void Save(string path){var data=new {id=Id,deviceId=DeviceId,root=Root,endpoint=Endpoint,isLocal=IsLocal,created=Created.ToString("o"),partial=Partial,skipped=Skipped,nodes=Nodes.Values.Where(x=>!x.Removed).Select(x=>new{id=x.Id,parent=x.Parent,name=x.Name,path=x.Path,directory=x.Directory,bytes=x.Bytes,stamp=x.Stamp.ToString("o"),incomplete=x.Incomplete}).ToArray()};string text=new JavaScriptSerializer{MaxJsonLength=160000000,RecursionLimit=20}.Serialize(data);Directory.CreateDirectory(System.IO.Path.GetDirectoryName(path));string temp=path+".tmp";using(var output=File.Create(temp))using(var zip=new GZipStream(output,CompressionMode.Compress))using(var writer=new StreamWriter(zip,new System.Text.UTF8Encoding(false)))writer.Write(text);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
 public static StorageSnapshot Load(string path){if(!File.Exists(path))return null;try{string text;using(var input=File.OpenRead(path))using(var zip=new GZipStream(input,CompressionMode.Decompress))using(var reader=new StreamReader(zip)) {var buffer=new char[8192];var content=new System.Text.StringBuilder();int count;while((count=reader.Read(buffer,0,buffer.Length))>0){content.Append(buffer,0,count);if(content.Length>160000000)return null;}text=content.ToString();}var obj=new JavaScriptSerializer{MaxJsonLength=160000000,RecursionLimit=20}.Deserialize<Dictionary<string,object>>(text);var s=new StorageSnapshot{Endpoint=obj.ContainsKey("endpoint")?Convert.ToString(obj["endpoint"]):"",Id=Convert.ToString(obj["id"]),DeviceId=Convert.ToString(obj["deviceId"]),Root=Convert.ToString(obj["root"]),IsLocal=Convert.ToBoolean(obj["isLocal"]),Created=DateTime.Parse(Convert.ToString(obj["created"]),null,System.Globalization.DateTimeStyles.RoundtripKind),Partial=Convert.ToBoolean(obj["partial"]),Skipped=Convert.ToInt32(obj["skipped"])};foreach(Dictionary<string,object> n in (System.Collections.IEnumerable)obj["nodes"]){var node=new StorageNode{Id=Convert.ToString(n["id"]),Parent=n["parent"]==null?null:Convert.ToString(n["parent"]),Name=Convert.ToString(n["name"]),Path=Convert.ToString(n["path"]),Directory=Convert.ToBoolean(n["directory"]),Bytes=Convert.ToInt64(n["bytes"]),Stamp=DateTime.Parse(Convert.ToString(n["stamp"]),null,System.Globalization.DateTimeStyles.RoundtripKind),Incomplete=Convert.ToBoolean(n["incomplete"])};s.Nodes.Add(node.Id,node);}foreach(var n in s.Nodes.Values)if(n.Parent!=null&&s.Nodes.ContainsKey(n.Parent))s.Nodes[n.Parent].Children.Add(n.Id);s.Aggregate();return s;}catch{return null;}}
}
public sealed class StorageScanJob {
 public readonly object Gate=new object();public readonly CancellationTokenSource Cancel=new CancellationTokenSource();public readonly ManualResetEventSlim Resume=new ManualResetEventSlim(true);public readonly Stopwatch Clock=Stopwatch.StartNew();public readonly Server Device;public readonly StorageSnapshot Result;
 public string Status="queued",Current="",Error="";public int Enumerated,Skipped;public long Bytes;public Task Work;
 public StorageScanJob(Server device,string root){Device=device.Copy();Result=new StorageSnapshot{Id=Guid.NewGuid().ToString("N"),DeviceId=PreviewDevices.Id(device),Root=root,Endpoint=StorageSnapshot.EndpointFor(device),IsLocal=device.IsLocal,Created=DateTime.UtcNow};}
 public object View(){lock(Gate)return new{id=Result.Id,deviceId=Result.DeviceId,root=Result.Root,status=Status,enumerated=Enumerated,skipped=Skipped,bytes=Bytes,current=Current,seconds=(int)Clock.Elapsed.TotalSeconds,error=Error,partial=Result.Partial};}
 public async Task Run(){try{lock(Gate)Status="enumerating";using(var connection=new FileConnection(Device)){await connection.Connect(Cancel.Token).ConfigureAwait(false);string root=string.IsNullOrWhiteSpace(Result.Root)?connection.Home:PreviewFileCopy.Normalize(Device.IsLocal,Result.Root);PreviewFileCopy.SafePath(connection,root);if(!connection.IsDirectory(root))throw new IOException("请选择可读取的文件夹");Result.Root=root;var top=new StorageNode{Id="0",Name=System.IO.Path.GetFileName(root.TrimEnd('/','\\')),Path=root,Directory=true,Stamp=DateTime.UtcNow};if(string.IsNullOrEmpty(top.Name))top.Name=root;Result.Nodes.Add(top.Id,top);var stack=new Stack<Tuple<StorageNode,int>>();stack.Push(Tuple.Create(top,0));int sequence=0;while(stack.Count>0){Cancel.Token.ThrowIfCancellationRequested();Resume.Wait(Cancel.Token);var next=stack.Pop();var parent=next.Item1;lock(Gate)Current=parent.Path;if(next.Item2>128){parent.Incomplete=true;Skipped++;continue;}
    try{foreach(var entry in connection.Enumerate(parent.Path,Cancel.Token)){Cancel.Token.ThrowIfCancellationRequested();Resume.Wait(Cancel.Token);if(entry.IsLink||Excluded(entry.FullPath,entry.Name)){parent.Incomplete=true;Skipped++;continue;}if(sequence>=120000){Result.Partial=true;parent.Incomplete=true;stack.Clear();break;}var node=new StorageNode{Id=(++sequence).ToString(),Parent=parent.Id,Name=entry.Name,Path=entry.FullPath,Directory=entry.IsDirectory,Bytes=entry.IsDirectory?0:entry.Size,Stamp=entry.Modified.ToUniversalTime()};Result.Nodes.Add(node.Id,node);parent.Children.Add(node.Id);if(node.Directory)stack.Push(Tuple.Create(node,next.Item2+1));lock(Gate){Enumerated++;if(!node.Directory)Bytes+=node.Bytes;}}
    }catch(OperationCanceledException){throw;}catch(Exception){if(parent.Id=="0"||!connection.Connected)throw;parent.Incomplete=true;lock(Gate)Skipped++;}}
   }
   Cancel.Token.ThrowIfCancellationRequested();lock(Gate)Status="aggregating";Result.Skipped=Skipped;Result.Partial=Result.Partial||Skipped>0;Result.Aggregate();lock(Gate){Status="ready";Current="";}
  }catch(OperationCanceledException){lock(Gate){Status="cancelled";Current="";}}catch(Exception ex){lock(Gate){Status="failed";Error=ex.GetBaseException().Message;Current="";}}finally{Clock.Stop();}}
 public static bool Excluded(string path,string name){if(name.Equals(".asterhub-trash",StringComparison.OrdinalIgnoreCase)||name.Equals("$RECYCLE.BIN",StringComparison.OrdinalIgnoreCase)||name.Equals("System Volume Information",StringComparison.OrdinalIgnoreCase))return true;string p=path.Replace('\\','/').TrimEnd('/');return new[]{"/proc","/sys","/dev","/run"}.Any(x=>p==x||p.StartsWith(x+"/",StringComparison.Ordinal));}
}
